      for(const [i,id]of ids.entries()){ensureCurrent();const cal=scopedCalendars().find(c=>c.id===id);status(`Reading calendar ${i+1} of ${ids.length}: ${cal?.summary||id}…`,'progress');const source=cal?await currentReader.readSource(cal,range,{signal:readController.signal}):{calendarId:id,items:[],coverage:{...range,complete:false,error:'Calendar unavailable or not selected for SlotDesk. Check Settings and the profile mapping.'},error:'Calendar unavailable or not selected for SlotDesk. Check Settings and the profile mapping.'};ensureCurrent();if(readController.signal.aborted)throw R.network(null,{cancelled:true});connectionError(source.failure);loaded.set(id,source);}
